public class CreationalPatterns1 {
    interface Spell { void cast(); }
    static class FireSpell implements Spell {
        public void cast() { System.out.println("Fireball cast!"); }
    }
    static class IceSpell implements Spell {
        public void cast() { System.out.println("Ice Lance cast!"); }
    }
    static class SpellFactory {
        static Spell create(String type) {
            return switch (type) {
                case "fire" -> new FireSpell();
                case "ice"  -> new IceSpell();
                default -> throw new IllegalArgumentException(type);
            };
        }
    }
    public static void main(String[] args) {
        SpellFactory.create("fire").cast();
        SpellFactory.create("ice").cast();
    }
}

