public class CreationalPatterns2 {
    static class Potion {
        final String name; final int power;
        private Potion(Builder b) { name = b.name; power = b.power; }
        static class Builder {
            String name; int power;
            Builder name(String n) { this.name = n; return this; }
            Builder power(int p) { this.power = p; return this; }
            Potion build() { return new Potion(this); }
        }
    }
    public static void main(String[] args) {
        Potion p = new Potion.Builder().name("Health Elixir").power(75).build();
        System.out.println(p.name);
        System.out.println(p.power);
    }
}

